    if fitting_bins_count > 0 {
        score -= (bin_capacity - bin_residual - item_size) as f64;
    }

    // Penalize bins with low residual space
    score += bin_residual as f64 * 0.1;

    // Reward using existing open bins
    if open_bins_count > 0 {
        score *= 1.2;
    }

    // Prioritize bins that can fit the next item as well
