pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins with very little remaining space
    if post_residual < 15 {
        score += (15 - post_residual) as f64 * 10.0;
    }

    // Reward using bins efficiently (closer to capacity is better)
    if bin_capacity - bin_residual <= 30 {
        score -= (bin_capacity - bin_residual - 30) as f64 * 2.0;
    }

    // Penalize opening new bins
    if open_bins_count > 1 {
        score += (open_bins_count - 1) as f64 * 5.0;
    }

    // Reward using fitting bins first
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Penalize looking ahead at very large items that don't fit well
    if next_item_size > 60 && post_residual < next_item_size - 20 {
        score += (next_item_size - post_residual - 20) as f64 * 7.0;
    }

    // Reward using bins with lower mean residual for better load balancing
    score -= (mean_residual / bin_capacity) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalty for low residual space with no fitting bins
    if bin_residual < item_size * 1.5 && fitting_bins_count == 0 {
        score -= 200.0;
    }

    // Reward for zero post-residual and available fitting bins
    if post_residual == 0 && fitting_bins_count > 0 {
        score += 75.0;
    }

    // Penalize open bins at the start of the process
    if step_index < total_items / 4 { // Adjusted threshold for earlier reduction
        score -= (open_bins_count as f64) * 15.0;
    }

    // Reward for fitting bins and post-residual above mean residual
    if fitting_bins_count > 0 && post_residual > mean_residual {
        score += 20.0; // Increased reward to encourage better compaction
    }

    // Penalize very low post-residual
    if post_residual < 15 { // Adjusted threshold for more severe penalty
        score -= 30.0;
    }

    // Reward for next item size compatibility with post-residual
    if next_item_size > 0 && post_residual >= next_item_size * 1.2 {
        score += 25.0; // Adjusted reward to balance lookahead and current fit
    }

    // Penalize large gap between mean residual and post-residual
    let residual_gap = (mean_residual - post_residual).abs();
    if residual_gap > bin_capacity / 4 { // Adjusted threshold for more severe penalty
        score -= residual_gap as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalty if remaining space is less than item size and no fitting bins available
    if bin_residual < item_size * 1.5 && fitting_bins_count == 0 {
        score -= 200.0;
    }

    // Reward if post-residual is zero and there are fitting bins available
    if post_residual == 0 && fitting_bins_count > 0 {
        score += 60.0;
    }

    // Penalty if step index is less than half of total items
    if step_index < total_items / 2 {
        score -= (open_bins_count as f64) * 15.0;
    }

    // Reward if there are fitting bins available and post-residual is greater than mean residual
    if fitting_bins_count > 0 && post_residual > mean_residual {
        score += 20.0;
    }

    // Penalty if post-residual is less than 20
    if post_residual < 15 {
        score -= 30.0;
    }

    // Reward if next item size is greater than zero and post-residual is at least 1.5 times the next item size
    if next_item_size > 0 && post_residual >= next_item_size * 1.2 {
        score += 40.0;
    }

    // Penalize difference between mean residual and post-residual
    score -= (mean_residual - post_residual) as f64 * 0.2;

    // Penalize if next item size is not zero and post-residual is at least the next item size
    if next_item_size != 0 && post_residual >= next_item_size {
        score -= (next_item_size / 20.0) as f64;
    }

    score
}
